/**
 * Real `attributedBody` typedstream blobs extracted from a personal backup,
 * chosen because their decoded text is short and innocuous. Used by both the
 * decoder unit tests and the queries fixture.
 *
 * hex -> Buffer helper included so tests read as plain hex.
 */
export function hex(h: string): Buffer {
  return Buffer.from(h.replace(/\s+/g, ""), "hex");
}

// Simple NSAttributedString wrapping an NSString. Decodes to "What are you up to? "
export const BLOB_SIMPLE =
  "";
export const BLOB_SIMPLE_TEXT = "What are you up to? ";

// NSMutableAttributedString wrapper. Decodes to "Did you just get there? "
export const BLOB_MUTABLE =
  "";
export const BLOB_MUTABLE_TEXT = "Did you just get there? ";

// Multi-byte UTF-8 (two 💕 emoji). Decodes to "Miss you two! 💕💕"
export const BLOB_EMOJI =
  "";
export const BLOB_EMOJI_TEXT = "Miss you two! 💕💕";

// Empty backing NSString (2B 00) — attachment placeholder. Decodes to null.
export const BLOB_EMPTY =
  "040B73747265616D747970656481E803840140848484124E5341747472696275746564537472696E67008484084E534F626A656374008592848484084E53537472696E67019484012B008686";
